def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Find connected non-background components; the compact motif is the
    # largest component, while isolated cells are the points where it repeats.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append(comp)

    # Motif is the largest connected component (ties resolved by extent).
    motif_comp = max(comps, key=len)
    motif_colors = {grid[r][c] for r, c in motif_comp}
    marker_colors = [v for v in counts if v != bg and v not in motif_colors]
    if not marker_colors:
        marker_colors = [v for v in counts if v != bg and counts[v] == min(counts[x] for x in counts if x != bg)]
    marker = marker_colors[0]

    motif_cells = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and grid[r][c] != marker]
    r0, r1 = min(r for r,c,v in motif_cells), max(r for r,c,v in motif_cells)
    c0, c1 = min(c for r,c,v in motif_cells), max(c for r,c,v in motif_cells)
    cr, cc = (r0+r1)//2, (c0+c1)//2
    offsets = [(r-cr,c-cc,v) for r,c,v in motif_cells]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr,dc,v in offsets:
                    rr, xx = r+dr, c+dc
                    if 0 <= rr < h and 0 <= xx < w:
                        out[rr][xx] = v
    return out
